Before submitting the answer, each selected bill needs a monetary total derived from its content, and the selected evidence and aggregate must be reviewed for missing values.

```python
def number_tokens(text):
    tokens = []
    token = ""
    for character in text:
        if character.isdigit() or (character in ".,-" and token):
            token += character
        elif character == "-":
            token = character
        else:
            cleaned = token.strip(".,")
            if any(character.isdigit() for character in cleaned):
                tokens.append(cleaned)
            token = ""
    cleaned = token.strip(".,")
    if any(character.isdigit() for character in cleaned):
        tokens.append(cleaned)
    return tokens

def token_to_cents(token):
    cleaned = token.replace(",", "")
    sign = -1 if cleaned.startswith("-") else 1
    cleaned = cleaned.lstrip("+-")
    if "." in cleaned:
        whole, fraction = cleaned.split(".", 1)
    else:
        whole, fraction = cleaned, ""
    whole_digits = "".join(character for character in whole if character.isdigit()) or "0"
    fraction_digits = "".join(character for character in fraction if character.isdigit())
    return sign * (int(whole_digits) * 100 + int((fraction_digits + "00")[:2]))

amount_labels = ["total amount due", "amount due", "total due", "balance due", "bill total", "total", "amount", "cost", "charge"]
parsed_cable_bills = []
for cable_bill in cable_bill_candidates:
    bill_lines = cable_bill["content"].splitlines()
    chosen_label = None
    chosen_line = None
    for amount_label in amount_labels:
        matching_lines = [line for line in bill_lines if amount_label in line.casefold()]
        if matching_lines:
            chosen_label = amount_label
            chosen_line = matching_lines[-1]
            break
    amount_cents = None
    if chosen_line is not None:
        label_end = chosen_line.casefold().find(chosen_label) + len(chosen_label)
        amount_text = chosen_line[label_end:]
        if "$" in amount_text:
            currency_tokens = []
            for currency_part in amount_text.split("$")[1:]:
                part_tokens = number_tokens(currency_part)
                if part_tokens:
                    currency_tokens.append(part_tokens[0])
            amount_token = currency_tokens[-1] if currency_tokens else None
        else:
            plain_tokens = number_tokens(amount_text)
            amount_token = plain_tokens[0] if plain_tokens else None
        if amount_token is not None:
            amount_cents = token_to_cents(amount_token)
    parsed_cable_bills.append({"path": cable_bill["path"], "evidence_line": chosen_line, "amount_cents": amount_cents})
if not cable_bill_candidates:
    raise ValueError("No current-year cable bill candidates were found")
unparsed_bill_paths = [bill["path"] for bill in parsed_cable_bills if bill["amount_cents"] is None]
if unparsed_bill_paths:
    raise ValueError("Could not derive a billed total for: " + ", ".join(unparsed_bill_paths))
total_cable_cost_cents = sum(bill["amount_cents"] for bill in parsed_cable_bills)
total_cable_cost = total_cable_cost_cents / 100
print({"matched_bill_count": len(parsed_cable_bills), "parsed_bills": parsed_cable_bills, "total_cable_cost": total_cable_cost})
