```python
transaction_pages = {}
target_transactions_by_id = {}
for friend_email in friend_emails:
    transaction_page_index = 0
    while True:
        transaction_page = apis.venmo.show_transactions(
            access_token=venmo_access_token,
            user_email=friend_email,
            min_created_at=window_start_date,
            direction="received",
            page_index=transaction_page_index,
            page_limit=20,
        )
        transaction_pages[(friend_email, transaction_page_index)] = transaction_page
        if not transaction_page:
            break
        for transaction in transaction_page:
            created_date = transaction["created_at"][:10]
            sender_email = transaction["sender"]["email"].strip().lower()
            receiver_email = transaction["receiver"]["email"].strip().lower()
            if (
                window_start_date <= created_date <= window_end_date
                and sender_email == friend_email
                and receiver_email == supervisor_email
            ):
                target_transactions_by_id[transaction["transaction_id"]] = transaction
        transaction_page_index += 1
print({
    "target_count": len(target_transactions_by_id),
    "target_transaction_ids": sorted(target_transactions_by_id),
})
```

