    verification_song_page = apis.spotify.show_song_library(access_token=spotify_access_token, page_index=verification_song_page_index, page_limit=20)
    verified_song_library_records.extend(verification_song_page)
    if len(verification_song_page) < 20:
        break
    verification_song_page_index += 1
verified_playlist_library_records = []
