while True:
    verification_playlist_page = apis.spotify.show_playlist_library(access_token=spotify_access_token, page_index=verification_playlist_page_index, page_limit=20)
    verified_playlist_library_records.extend(verification_playlist_page)
    if len(verification_playlist_page) < 20:
        break
    verification_playlist_page_index += 1
verified_playlist_ids = sorted({record["playlist_id"] for record in verified_playlist_library_records})
verified_playlist_details_by_id = {}
for playlist_id in verified_playlist_ids:
    verified_playlist_details_by_id[playlist_id] = apis.spotify.show_playlist(playlist_id=playlist_id, access_token=spotify_access_token)
verified_library_song_ids = {record["song_id"] for record in verified_song_library_records}
verified_playlist_pairs = {(playlist_id, song["id"]) for playlist_id, detail in verified_playlist_details_by_id.items() for song in detail["songs"]}
verified_remaining_song_ids = verified_library_song_ids | {song_id for _, song_id in verified_playlist_pairs}
verified_song_details_by_id = {}
for song_id in sorted(verified_remaining_song_ids):
    verified_song_details_by_id[song_id] = apis.spotify.show_song(song_id=song_id)
verified_release_year_by_song_id = {song_id: int(detail["release_date"][:4]) for song_id, detail in verified_song_details_by_id.items()}
remaining_old_library_ids = sorted(song_id for song_id in verified_library_song_ids if verified_release_year_by_song_id[song_id] < cutoff_year)
remaining_old_playlist_pairs = sorted((playlist_id, song_id) for playlist_id, song_id in verified_playlist_pairs if verified_release_year_by_song_id[song_id] < cutoff_year)
original_library_targets_remaining = sorted(set(library_removal_ids) & verified_library_song_ids)
original_playlist_targets_remaining = sorted(set(reviewed_playlist_removal_pairs) & verified_playlist_pairs)
verification_ok = not remaining_old_library_ids and not remaining_old_playlist_pairs and not original_library_targets_remaining and not original_playlist_targets_remaining
verification_summary = {"remaining_pre_2021_library_songs": len(remaining_old_library_ids), "remaining_pre_2021_playlist_entries": len(remaining_old_playlist_pairs), "original_library_targets_still_present": len(original_library_targets_remaining), "original_playlist_targets_still_present": len(original_playlist_targets_remaining), "verification_ok": verification_ok}
